export const signUp = async (data: any) => {
  try {
    const response = await sparta_games.post("/accounts/api/signup/", data);

    return response;
  } catch (error) {
    throw error;
  }
};

export const postSendEmailCode = async (email: string, isNew: boolean) => {
  try {
    const response = await sparta_games.post("/accounts/api/email/", {
      email,
      is_new: isNew,
    });

    return response;
  } catch (error: unknown) {
    if (axios.isAxiosError(error) && error.response) {
      return error.response;
    }
  }
};

export const postEmailVerify = async (email: string, code: number) => {
  try {
    const response = await sparta_games.post("/accounts/api/email-verify/", {
      email,
      code,
    });
    return response;
  } catch (error: unknown) {
    if (axios.isAxiosError(error) && error.response) {
      return error.response;
    }
  }
};

import { useQuery } from "@tanstack/react-query";
import { getRegisterGameDetail } from "../../api/direct";
import { formatToKST } from "../../util/formatToKST";

type Props = {
  game_id: number;
};

function AdminLogsModal({ game_id }: Props) {
  const { data } = useQuery({
    queryKey: ["gameLog", game_id],
    queryFn: () => getRegisterGameDetail(game_id),
  });

  return (
    <div className="w-[600px] pt-2">
      <div className="w-full border-gray-100 rounded-lg border-[1px] border-solid items-center flex px-4 py-4 overflow-auto flex-col gap-2 max-h-[400px]">
        {data && data.data && data.data.length > 0 ? (
          data.data.map((item: any, idx: number) => (
            <div key={idx} className="text-white  flex items-center gap-3 w-full">
              <p>{formatToKST(item.created_at)}</p>
              <p>{item.content}</p>
            </div>
          ))
        ) : (
          <p className="text-white font-DungGeunMo text-heading-28 flex items-center justify-center w-full h-20">
            게임 로그가 없습니다.
          </p>
        )}
      </div>
    </div>
  );
}

export default AdminLogsModal;

import React from "react";

type TSpartaSelectableGroupProps = {
  /**
   * 선택 가능한 데이터
   */
  selectableData: { label: string; value: any }[];
  /**
   * 선택된 데이터 변경 시 호출되는 함수
   */
  onChangeSelectedData: (selectedData: { label: string; value: any }[]) => void;
  /**
   * 다중 선택 가능 여부
   */
  isMultipleSelect?: boolean;
  /**
   * 초기 선택 데이터
   */
  initialSelectedData?: { label: string; value: any }[];
  /**
   * 초기화 버튼 유무
   */
  isResetButton?: boolean;
  /**
   * disabled 여부
   */
  disabled?: boolean;
};

const SpartaSelectableGroup = (props: TSpartaSelectableGroupProps) => {
  //* State
  const [selectedData, setSelectedData] = React.useState<{ label: string; value: any }[]>([]);

  //* Function
  /**
   * 선택 시 호출되는 함수
   */
  const onSelect = (data: { label: string; value: any }) => {
    if (props.disabled) return;
    if (props.isMultipleSelect) {
      // 다중 선택
      if (selectedData.find((item) => item.value === data.value)) {
        // 이미 선택된 데이터라면 제거
        setSelectedData(selectedData.filter((item) => item.value !== data.value));
        props.onChangeSelectedData(selectedData.filter((item) => item.value !== data.value));
      } else {
        // 선택되지 않은 데이터라면 추가
        setSelectedData([...selectedData, data]);
        props.onChangeSelectedData([...selectedData, data]);
      }
    } else {
      // 단일 선택
      setSelectedData([data]);
      props.onChangeSelectedData([data]);
    }
  };
  /**
   * 리셋 버튼 클릭 시
   */
  const onClickResetButton = () => {
    if (props.disabled) return;
    setSelectedData([]);
    props.onChangeSelectedData([]);
  };

  //* Hooks

  React.useEffect(() => {
    if (props.initialSelectedData) {
      setSelectedData(props.initialSelectedData);
    }
  }, [props.initialSelectedData]);

  //* Style
  const getButtonStyle = (index: number) => {
    const isFirst = index === 0;
    const isLast = index === props.selectableData.length - 1;
    const isSelected = selectedData.find((data) => data.value === props.selectableData[index].value);

    let roundedClass = "";
    if (props.selectableData.length === 2) {
      // 2개일 때는 왼쪽, 오른쪽 모서리만 처리
      roundedClass = isFirst ? "rounded-l-md" : "rounded-r-md";
    } else {
      // 2개 이상일 때는 각 모서리 처리
      if (isFirst) roundedClass = "rounded-tl-md";
      if (isLast && props.selectableData.length % 2 === 0) roundedClass = "rounded-br-md";
      if (props.selectableData.length % 2 === 0 && index === 1) roundedClass = "rounded-tr-md";
      if (props.selectableData.length % 2 === 0 && index === props.selectableData.length - 2)
        roundedClass = "rounded-bl-md";
    }

    return `py-4 transition-colors border-[1px] flex justify-center ${roundedClass} ${
      isSelected
        ? "bg-gray-800 text-primary-500 border-primary-500"
        : "bg-gray-800 text-gray-300 hover:bg-gray-700 border-gray-100 border-[1px]"
    }`;
  };

  return (
    <div
      className={`grid bg-gray-700 rounded-md overflow-hidden ${
        props.selectableData.length === 2 ? "grid-cols-2" : "grid-cols-2"
      } bg-gray-800`}
    >
      {props.selectableData.map((item, index) => (
        <button key={item.value} onClick={() => onSelect(item)} className={getButtonStyle(index)}>
          {item.label}
        </button>
      ))}
      {props.isResetButton && (
        <button
          onClick={onClickResetButton}
          className="col-span-2 py-4 flex justify-center bg-gray-800 text-gray-300 hover:bg-gray-700 border-gray-300 "
        >
          초기화
        </button>
      )}
    </div>
  );
};

export default SpartaSelectableGroup;

import { useSaveVerification } from "../../../../hook/useSaveVerification";
import { getTeamBuildProfileByUserId } from "../../../../api/teambuilding";
import { useEffect, useMemo, useRef, useState } from "react";
import { useForm, FormProvider } from "react-hook-form";
import { useLocation, useNavigate } from "react-router-dom";
import { useMutation } from "@tanstack/react-query";

import CommunityProjectTitle from "../../../common/CommunityProjectTitle";
import ProfileRegisterFormProject from "./ProfileRegisterFormProject";
import PorfileRegisterFormBasic from "./ProfileRegisterFormBasic";
import SpartaButton from "../../../../spartaDesignSystem/SpartaButton";

import { TProfileRegisterForm } from "../../../../types";

import { postTeamBuildProfile, putTeamBuildProfile } from "../../../../api/teambuilding";
import useModalToggles from "../../../../hook/useModalToggles";
import SpartaReactionModal, { TSpartaReactionModalProps } from "../../../../spartaDesignSystem/SpartaReactionModal";
import { userStore } from "../../../../share/store/userStore";

import recruitImage from "../../../../assets/gameDetail/ReviewEdit.svg";
import arrowBack from "../../../../assets/common/arrow/triangleArrowLeft.svg";

export default function ProfileRegisterForm() {
  const methods = useForm<TProfileRegisterForm>({
    mode: "onChange",
    defaultValues: {
      portfolio: [{ link: "", type: "portfolio" }],
    },
  });
  const { watch, formState, trigger } = methods;

  const { userData } = userStore();

  const navigate = useNavigate();
  const verification = useSaveVerification();
  const location = useLocation();
  const { profileData, isEditMode } = location.state || {};

  const [currentStep, setCurrentStep] = useState(0);
  const isInitialSet = useRef(false);

  useEffect(() => {
    if (isEditMode && profileData && !isInitialSet.current) {
      const defaultPortfolio =
        profileData.portfolio && profileData.portfolio.length > 0
          ? profileData.portfolio
          : [{ link: "", type: "portfolio" }];

      methods.reset({ ...profileData, portfolio: defaultPortfolio });
      isInitialSet.current = true;
    }
  }, [isEditMode, profileData, methods]);

  const goToNextStep = () => {
    setCurrentStep((prev) => prev + 1);
    trigger();
  };
  const goToPrevStep = () => {
    setCurrentStep((prev) => prev - 1);
    trigger();
  };

  const CONFIRM_MODAL_ID = "confirmModal";
  const SUCCESS_MODAL_ID = "successModal";
  const FAIL_MODAL_ID = "failModal";
  const { modalToggles, onClickModalToggleHandlers } = useModalToggles([
    CONFIRM_MODAL_ID,
    SUCCESS_MODAL_ID,
    FAIL_MODAL_ID,
  ]);

  const noActionData: { [key: string]: Partial<TSpartaReactionModalProps> } = {
    uploadConfirm: {
      title: !isEditMode ? "글 등록" : "글 수정",
      content: !isEditMode ? "작성하신 내용으로 팀빌딩 프로필을 등록하시겠어요?" : "이대로 수정하시겠어요?",
      btn1: {
        text: !isEditMode ? "네 등록할게요." : "네 수정할게요.",
        onClick: () => {},
      },
      btn2: {
        text: "아니요. 좀 더 수정할게요.",
        onClick: () => {
          onClickModalToggleHandlers[CONFIRM_MODAL_ID]();
        },
      },
    },
    uploadSuccess: {
      title: !isEditMode ? "글 등록 완료" : "글 수정 완료",
      content: !isEditMode ? "팀빌딩 프로필이 성공적으로 등록되었습니다." : "팀원 모집 글이 성공적으로 수정되었습니다.",
      btn1: {
        text: "확인했습니다",
        onClick: () => {
          onClickModalToggleHandlers[CONFIRM_MODAL_ID]();
        },
      },
    },
  };

  const [noActionModalData, setNoActionModalData] = useState<Partial<TSpartaReactionModalProps>>(
    noActionData.uploadSuccess,
  );

  const onSubmitProfileRegister = () => {
    if (!isPending) methods.handleSubmit(onSubmit)();
  };

  const isStepOneValid = useMemo(() => {
    const myRole = watch("my_role");
    const techStack = watch("tech_stack");

    return !!myRole && !!techStack; // 조건에 맞게 true/false 리턴
  }, [watch()]);

  const onSubmit = (data: any) => {
    if (isPending) return;
    const formData = new FormData();

    if (data.profile_image?.[0] instanceof File) formData.append("image", data.profile_image[0]);
    formData.append("career", data.career);
    formData.append("my_role", data.my_role);
    formData.append("tech_stack", data.tech_stack);
    formData.append("purpose", data.purpose);
    formData.append("duration", data.duration);
    formData.append("meeting_type", data.meeting_type);
    formData.append("contact", data.contact);
    formData.append("title", data.title);
    formData.append("content", data.content);

    data.game_genre.forEach((genre: string) => {
      formData.append("game_genre", genre);
    });

    if (data.portfolio && data.portfolio.length > 0) {
      data.portfolio.forEach((portfolio: { portfolio: string; type: string }) => {
        formData.append("portfolio", JSON.stringify(portfolio));
      });
    }

    if (!isEditMode) {
      createTeamBuildProfileMutation.mutate(formData);
    } else {
      updateTeamBuildProfileMutation.mutate({ userId: userData?.data.user_id, formData });
    }
  };

  const createTeamBuildProfileMutation = useMutation({
    mutationFn: postTeamBuildProfile,
    onSuccess: (data) => {
      setNoActionModalData({
        title: "글 등록 완료",
        content:
          data.status === "warning" ? "글은 등록되었지만 이미지 처리에 문제가 있습니다." : "글 등록이 완료됐습니다!",
        btn1: {
          text: "확인했습니다.",
          onClick: () => {
            onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
            navigate(`/my-page/${userData?.data.user_id}?tab=teambuilding`, { replace: true });
          },
        },
        type: "primary",
      });
      onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
    },
    onError: () => {
      verification.setMessage(
        "요청 결과를 확인하지 못했습니다. 입력 내용을 유지한 채 프로필에서 등록 여부를 확인해주세요.",
      );
    },
  });

  const updateTeamBuildProfileMutation = useMutation({
    mutationFn: ({ userId, formData }: { userId: number | undefined; formData: FormData }) =>
      putTeamBuildProfile(userId, formData),

    onSuccess: (data) => {
      setNoActionModalData({
        title: "글 수정 완료",
        content:
          data.status === "warning"
            ? "변경사항이 저장되었지만 이미지 처리에 문제가 있습니다."
            : "글 수정이 완료됐습니다!",
        btn1: {
          text: "확인했습니다.",
          onClick: () => {
            onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
            navigate(`/my-page/${userData?.data.user_id}?tab=teambuilding`, { replace: true });
          },
        },
        type: "primary",
      });
      onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
    },
    onError: async () => {
      await verification.verify(
        () => getTeamBuildProfileByUserId(userData?.data.user_id),
        methods.getValues() as unknown as Record<string, unknown>,
      );
    },
  });

  const isPending =
    verification.checking ||
    (isEditMode ? updateTeamBuildProfileMutation.isPending : createTeamBuildProfileMutation.isPending);

  return (
    <div className="mx-auto mt-16">
      {verification.message && (
        <div role="status" className="p-4 text-white bg-gray-800">
          <p>{verification.message}</p>
          {isEditMode && (
            <button type="button" onClick={() => navigate(`/my-page/${userData?.data.user_id}?tab=teambuilding`)}>
              상세 확인
            </button>
          )}
        </div>
      )}
      <div className="flex justify-center items-center mb-6">
        <div
          onClick={currentStep === 0 ? undefined : goToPrevStep}
          className={`flex items-center justify-center w-6 h-6 border border-solid ${
            currentStep === 0 ? "border-green-500 text-green-500" : "border-gray-400 text-gray-400"
          } rounded-full cursor-pointer`}
        >
          <span className="font-DungGeunMo text-xl">1</span>
        </div>

        <div className="h-0.5 w-5 bg-gray-500"></div>

        <div
          onClick={currentStep === 1 ? undefined : goToNextStep}
          className={`flex items-center justify-center w-6 h-6 border border-solid ${
            currentStep === 1 ? "border-green-500 text-green-500" : "border-gray-400 text-gray-400"
          } rounded-full cursor-pointer`}
        >
          <span className="font-DungGeunMo text-xl">2</span>
        </div>
      </div>

      <div className="relative flex items-center w-full">
        <img
          className={`${currentStep === 0 ? "hidden" : "block"} absolute left-0 cursor-pointer`}
          onClick={goToPrevStep}
          src={arrowBack}
          alt="1페이지 폼으로 돌아가기"
        />
        <div className="flex-1 text-center">
          <CommunityProjectTitle img={recruitImage} title={"프로필을 등록하고 프로젝트를 시작해보세요"} />
        </div>
      </div>

      <FormProvider {...methods}>
        <form onSubmit={methods.handleSubmit(onSubmit)}>
          <div className="w-[1000px] mx-auto">
            {currentStep === 0 && <PorfileRegisterFormBasic profileData={profileData} isEditMode={isEditMode} />}
            {currentStep === 1 && <ProfileRegisterFormProject />}
            <SpartaButton
              disabled={currentStep === 0 ? !isStepOneValid : !formState.isValid || isPending}
              onClick={currentStep === 0 ? goToNextStep : onSubmitProfileRegister}
              content={currentStep === 0 ? "다음" : !isEditMode ? "글 등록하기" : "글 수정하기"}
              type="filled"
              colorType="primary"
              btnType="button"
            />
          </div>
        </form>
      </FormProvider>
      {noActionModalData && (
        <>
          <SpartaReactionModal
            isOpen={modalToggles[CONFIRM_MODAL_ID]}
            onClose={onClickModalToggleHandlers[CONFIRM_MODAL_ID]}
            modalId={CONFIRM_MODAL_ID}
            title={noActionModalData.title || ""}
            content={noActionModalData.content || ""}
            btn1={{
              text: noActionModalData?.btn1?.text || "",
              onClick: () => {
                if (!isPending) methods.handleSubmit(onSubmit)();
              },
            }}
            btn2={
              noActionModalData?.btn2 && {
                text: noActionModalData?.btn2?.text || "",
                onClick: noActionModalData?.btn2?.onClick || (() => {}),
              }
            }
            type={noActionModalData.type}
          />

          <SpartaReactionModal
            isOpen={modalToggles[SUCCESS_MODAL_ID]}
            onClose={onClickModalToggleHandlers[SUCCESS_MODAL_ID]}
            modalId={SUCCESS_MODAL_ID}
            title={noActionModalData.title || ""}
            content={noActionModalData.content || ""}
            closeOnClickOutside={false}
            btn1={{
              text: noActionModalData?.btn1?.text || "확인",
              onClick: noActionModalData?.btn1?.onClick || (() => onClickModalToggleHandlers[SUCCESS_MODAL_ID]()),
            }}
          />
        </>
      )}
    </div>
  );
}

import { ChangeEvent, useEffect, useState } from "react";
import { Controller, useFieldArray, useFormContext } from "react-hook-form";
import { FormControl, MenuItem, OutlinedInput, Select, styled } from "@mui/material";

import SpartaChipSelect from "../../../../spartaDesignSystem/SpartaChipSelect";
import SpartaRadioGroup from "../../../../spartaDesignSystem/SpartaRadioGroup";
import SpartaTextField from "../../../../spartaDesignSystem/SpartaTextField";

import { GAME_CATEGORY } from "../../../../constant/constant";
import { TProfileRegisterForm, TTeamBuildProfileListItem } from "../../../../types";

import { useTeamBuildRadioOptions } from "../../../../hook/useTeamBuildRadioOptions ";
import { useRoleOptions } from "../../../../hook/useRoleOptions";

import profileImageUpload from "../../../../assets/communityImage/profileImageUpload.png";
import addBtn from "../../../../assets/common/plus_gray.svg";
import removeBtn from "../../../../assets/common/deleteIcon_trash.png";
import defaultProfile from "../../../../assets/common/defaultProfile.svg";

type Props = {
  profileData: TTeamBuildProfileListItem;
  isEditMode: boolean;
};
export default function PorfileRegisterFormBasic({ profileData, isEditMode }: Props) {
  const { register, control, setValue, watch, formState } = useFormContext<TProfileRegisterForm>();

  const { fields, append, remove } = useFieldArray({
    control,
    name: "portfolio",
  });

  const [profilePreview, setProfilePreview] = useState<string | null>(null);
  const [borderActiveStates, setBorderActiveStates] = useState<boolean[]>([]);

  const { radioGroupsData } = useTeamBuildRadioOptions();
  const { roleOptions } = useRoleOptions();

  useEffect(() => {
    setBorderActiveStates((prev) => {
      const diff = fields.length - prev.length;

      if (diff > 0) {
        // 새로 추가된 Select 박스의 기본 테두리 색으로 변경하고 기존 Select 박스의 변경된 테두리 색은 유지
        return [...prev, ...Array(diff).fill(false)];
      }

      return prev.slice(0, fields.length); // 필드가 삭제된 경우 이전 상태와 길이 맞춤
    });
  }, [fields.length]);

  useEffect(() => {
    const profileImage = watch("profile_image")?.[0];

    if (profileImage instanceof File) {
      const previewUrl = URL.createObjectURL(profileImage);
      setProfilePreview(previewUrl);

      return () => URL.revokeObjectURL(previewUrl);
    } else if (isEditMode && profileData?.profile_image) {
      const imageUrl =
        import.meta.env.VITE_DEPLOYMENT_MODE === "dev"
          ? import.meta.env.VITE_PROXY_HOST.replace(/\/$/, "") + profileData.profile_image
          : profileData.profile_image;
      setProfilePreview(imageUrl);
    } else {
      setProfilePreview(defaultProfile);
    }
  }, [watch]);

  const toggleBorderActive = (index: number) => {
    setBorderActiveStates((prev) => {
      const newStates = [...prev];
      newStates[index] = true;
      return newStates;
    });
  };

  const handleImageChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const previewUrl = URL.createObjectURL(file);
      setProfilePreview(previewUrl);
    }
  };

  const onClickAddLink = () => {
    append({ link: "", type: "portfolio" });
  };

  const onClickRemoveLink = (index: number) => {
    remove(index);
  };

  const MenuProps = {
    PaperProps: {
      style: {
        maxHeight: 40 * 4.5,
        backgroundColor: "#1A1A1A",
        color: "#FFF",
      },
    },
  };

  const CustomMenuItem = styled(MenuItem)({
    color: "#FFF",
    fontSize: "14px",
    backgroundColor: "#1A1A1A",
    "&:hover": {
      backgroundColor: "#333333",
    },
  });

  return (
    <div className="w-full mt-10 mb-6 p-9 bg-gray-800 rounded-xl">
      <p className="font-DungGeunMo text-xl text-primary-400 mb-4">기본 프로필 정보 작성</p>

      <div className="flex gap-10 w-full">
        <div className="flex flex-col basis-1/2 gap-5">
          <div className="flex flex-col gap-2">
            <span className="text-gray-50 text">프로필 이미지</span>

            <div className="flex items-end gap-2">
              <div className="border border-solid border-gray-400 rounded-sm">
                <img
                  className=" w-28 h-28 object-cotain rounded-sm"
                  src={
                    profilePreview ||
                    (profileData?.profile_image === null
                      ? defaultProfile
                      : import.meta.env.VITE_DEPLOYMENT_MODE === "dev"
                      ? import.meta.env.VITE_PROXY_HOST.replace(/\/$/, "") + profileData?.profile_image
                      : profileData?.profile_image)
                  }
                  alt="프로필 이미지"
                />
              </div>
              <label htmlFor="profile-image" className="cursor-pointer">
                <img className="w-8 h-8" src={profileImageUpload} alt="프로필 이미지 업로드" />
              </label>

              <input
                id="profile-image"
                type="file"
                accept="image/*"
                {...register("profile_image", {
                  onChange: (e) => {
                    handleImageChange(e);
                  },
                })}
                className="hidden"
              />
            </div>
          </div>

          <SpartaRadioGroup
            groupsToShow={["career"]}
            control={control}
            watch={watch}
            setValue={setValue}
            radioGroupsData={radioGroupsData}
          />

          <div className="flex flex-col gap-4 basis-full">
            <SpartaChipSelect
              label="나의 포지션"
              options={roleOptions}
              control={control}
              rules={{ required: "나의 포지션을 선택해주세요." }}
              name="my_role"
              placeHolderText="나의 포지션을 선택해주세요."
              subLabel={{
                default: "",
                error: formState.errors.my_role?.message as string,
                pass: "",
              }}
              error={!!formState.errors.my_role}
            />
          </div>
        </div>

        <div className="flex flex-col gap-5 basis-1/2">
          <SpartaTextField
            label="기술 스택 또는 툴"
            type="small"
            register={register("tech_stack", {
              required: "기술 스택 또는 툴을 입력해주세요.",
              maxLength: {
                value: 100,
                message: "최대 100자까지 입력 가능합니다.",
              },
            })}
            inputProps={{
              placeholder: "Unity, Unreal, Adobe 등",
              maxLength: 100,
            }}
            subLabel={{
              default: "",
              error: formState.errors.tech_stack?.message as string,
              pass: "",
            }}
            error={!!formState.errors.tech_stack}
          />

          <SpartaChipSelect
            label="관심 게임개발장르"
            warning={true}
            subLabel={{ warning: "*선택", error: "", pass: "", default: "" }}
            options={GAME_CATEGORY}
            control={control}
            name="game_genre"
            placeHolderText="관심 게임개발장르를 선택해주세요."
            multiple
          />

          <div className="flex flex-col">
            {fields.map((field, index) => (
              <div key={field.id} className="flex items-end gap-2">
                <div className="basis-[70%]">
                  <Controller
                    name={`portfolio.${index}.link`}
                    control={control}
                    defaultValue={field.link}
                    render={({ field }) => (
                      <SpartaTextField
                        label={index === 0 ? "포트폴리오 및 기타 링크" : ""}
                        warning={true}
                        subLabel={{ warning: index === 0 ? "*선택" : "", error: "", pass: "", default: "" }}
                        type="small"
                        inputProps={{
                          ...field,
                          placeholder: "https://",
                        }}
                      />
                    )}
                  />
                </div>

                <div className="basis-[30%]">
                  <div className="flex gap-2">
                    <Controller
                      name={`portfolio.${index}.type`}
                      control={control}
                      defaultValue={field.type}
                      render={({ field }) => (
                        <FormControl fullWidth>
                          <Select
                            {...field}
                            onClick={() => {
                              if (field.value === "portfolio" && !borderActiveStates[index]) {
                                toggleBorderActive(index);
                              }
                            }}
                            MenuProps={MenuProps}
                            input={<OutlinedInput />}
                            displayEmpty
                            sx={{
                              backgroundColor: "#1A1A1A",
                              color: "#FFF",
                              fontSize: "14px",
                              padding: "2px",
                              borderRadius: "6px",
                              "& .MuiOutlinedInput-notchedOutline": {
                                borderColor: borderActiveStates[index] ? "#fff" : "#737373",
                              },
                              "&:hover .MuiOutlinedInput-notchedOutline": {
                                borderColor: borderActiveStates[index] ? "#fff" : "#737373",
                              },
                              "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
                                borderColor: borderActiveStates[index] ? "#fff" : "#737373",
                              },
                              "& .MuiSelect-icon": {
                                color: "#E5E5E5",
                              },
                              "& .MuiInputBase-input": {
                                padding: "10px 14px",
                              },
                            }}
                          >
                            <CustomMenuItem value="portfolio">포트폴리오</CustomMenuItem>
                            <CustomMenuItem value="link">Link</CustomMenuItem>
                            <CustomMenuItem value="github">GitHub</CustomMenuItem>
                            <CustomMenuItem value="notion">Notion</CustomMenuItem>
                          </Select>
                        </FormControl>
                      )}
                    />
                    {index !== 0 && (
                      <button type="button" onClick={() => onClickRemoveLink(index)}>
                        <img src={removeBtn} alt="삭제" className="w-9 h-9" />
                      </button>
                    )}
