        },
        type: "primary",
      });

      onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
    },
    onError: (error: AxiosError) => {
      if (error.response && error.response.status === 400) {
        verification.setMessage(
          "요청 결과를 확인하지 못했습니다. 입력 내용을 유지한 채 목록에서 등록 여부를 확인해주세요.",
        );
      } else {
        verification.setMessage(
          "요청 결과를 확인하지 못했습니다. 입력 내용을 유지한 채 목록에서 등록 여부를 확인해주세요.",
        );
      }
    },
  });

  const updateTeamBuildingMutation = useMutation({
    mutationFn: ({ postId, formData }: { postId: number; formData: FormData }) => putTeamBuild(postId, formData),
    onSuccess: (data) => {
      setNoActionModalData({
        title: "글 수정 완료",
        content:
          data.status === "warning"
            ? "변경사항이 저장되었지만 이미지 처리에 문제가 있습니다."
            : "글 수정이 완료됐습니다!",
        btn1: {
          text: "확인했습니다.",
          onClick: () => {
            onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
            navigate(`/community/team-building/team-recruit/${data.data.post_id}`, { replace: true });
          },
        },
        type: "primary",
      });

      onClickModalToggleHandlers[SUCCESS_MODAL_ID]();
    },
    onError: async () => {
      await verification.verify(
        () => getTeamBuildDetail(postDetail.id),
        methods.getValues() as unknown as Record<string, unknown>,
      );
    },
  });

  const isPending =
    verification.checking || (isEditMode ? updateTeamBuildingMutation.isPending : createTeamBuildingMutation.isPending);

  const onSubmit = async (data: any) => {
    if (isPending) return;
    const formData = new FormData();

    formData.append("title", data.title);
    formData.append("purpose", data.purpose);
    formData.append("duration", data.duration);
    formData.append("meeting_type", data.meeting_type);
    formData.append("deadline", data.deadline);
    formData.append("contact", data.contact);
    formData.append("content", data.content);

    if (data.thumbnail?.[0] instanceof File) {
      formData.append("thumbnail", data.thumbnail[0]);
    } else if (!isEditMode) {
      formData.append("thumbnail_basic", "default");
    }

    data.want_roles.forEach((role: string) => {
      formData.append("want_roles", role);
    });

    if (!isEditMode) {
      createTeamBuildingMutation.mutate(formData);
    } else {
      updateTeamBuildingMutation.mutate({ postId: postDetail.id, formData });
    }
  };

  return (
    <>
      <div className="mx-auto mt-16">
        {verification.message && (
          <div role="status" className="p-4 text-white bg-gray-800">
            <p>{verification.message}</p>
            {isEditMode && (
              <button type="button" onClick={() => navigate(`/community/team-building/team-recruit/${postDetail.id}`)}>
                상세 확인
              </button>
            )}
          </div>
        )}
        <CommunityProjectTitle img={recruitImage} title={"프로젝트를 같이 만들 팀원을 구해요"} />

        <FormProvider {...methods}>
          <form onSubmit={handleSubmit(onSubmit)}>
            <div className="w-[997px] mx-auto">
              <RecruitFormBasicInfo postDetail={postDetail} />
              <RecruitFormDescription />
              <SpartaButton
                btnType="button"
                disabled={isPending || !formState.isValid}
                content={isPending ? "처리 중입니다." : !isEditMode ? "글 등록하기" : "글 수정하기"}
                type="filled"
                onClick={() => {
                  if (!isPending) handleSubmit(onSubmit)();
                }}
              />
            </div>
          </form>
        </FormProvider>
      </div>
      {noActionModalData && (
        <>
          <SpartaReactionModal
            isOpen={modalToggles[CONFIRM_MODAL_ID]}
            onClose={onClickModalToggleHandlers[CONFIRM_MODAL_ID]}
            modalId={CONFIRM_MODAL_ID}
            title={noActionModalData.title || ""}
            content={noActionModalData.content || ""}
            btn1={{
              text: noActionModalData?.btn1?.text || "",
              onClick: () => {
                if (!isPending) handleSubmit(onSubmit)();
              },
            }}
            btn2={
              noActionModalData?.btn2 && {
                text: noActionModalData?.btn2?.text || "",
                onClick: noActionModalData?.btn2?.onClick || (() => {}),
              }
            }
            type={noActionModalData.type}
          />

          <SpartaReactionModal
            isOpen={modalToggles[SUCCESS_MODAL_ID]}
            onClose={onClickModalToggleHandlers[SUCCESS_MODAL_ID]}
            modalId={SUCCESS_MODAL_ID}
            title={noActionModalData.title || ""}
            content={noActionModalData.content || ""}
            closeOnClickOutside={false}
            btn1={{
              text: noActionModalData?.btn1?.text || "확인",
              onClick: noActionModalData?.btn1?.onClick || (() => onClickModalToggleHandlers[SUCCESS_MODAL_ID]()),
            }}
          />
        </>
      )}
    </>
  );
}

import { forwardRef, useState } from "react";
import { Controller, useFormContext } from "react-hook-form";

import SpartaChipSelect from "../../../../spartaDesignSystem/SpartaChipSelect";
import SpartaTextField from "../../../../spartaDesignSystem/SpartaTextField";
import SpartaButton from "../../../../spartaDesignSystem/SpartaButton";
import SpartaCheckBox from "../../../../spartaDesignSystem/SpartaCheckBox";
import SpartaRadioGroup from "../../../../spartaDesignSystem/SpartaRadioGroup";

import { getFormattedDate } from "../../../../util/getFormattedDate";

import { TProjectRecruitForm, TTeamBuildPostDetail } from "../../../../types";

import DatePicker from "react-datepicker";
import { ko } from "date-fns/locale";
import { format, startOfDay, isBefore } from "date-fns";
import "react-datepicker/dist/react-datepicker.css";
import "./reactDatePickerCustomStyle.css";

import { useTeamBuildRadioOptions } from "../../../../hook/useTeamBuildRadioOptions ";
import { useRoleOptions } from "../../../../hook/useRoleOptions";

import calendar from "../../../../assets/common/calender.svg";

type Props = {
  postDetail: TTeamBuildPostDetail;
};
export default function RecruitFormBasicInfo({ postDetail }: Props) {
  const { control, watch, setValue, register, formState, trigger } = useFormContext<TProjectRecruitForm>();

  const imageWatch = watch("thumbnail");

  const [selectBasicImage, setSelectBasicImage] = useState(postDetail?.thumbnail_basic);
  const [isChecked, setIsChecked] = useState(postDetail?.thumbnail_basic);

  const { radioGroupsData } = useTeamBuildRadioOptions();
  const { roleOptions } = useRoleOptions();

  const onClickUploadImage = () => {
    document.getElementById("project-image")?.click();
  };

  const onClickSelectBasicImage = () => {
    setIsChecked((prev) => !prev);
    setSelectBasicImage((prev) => !prev);

    setValue("thumbnail_basic", "default");
    setValue("thumbnail", "");
    trigger("thumbnail"); // 필수!
  };

  const thumbnailWatch = watch("thumbnail");
  const thumbnailPlaceHolder = selectBasicImage // 기본 이미지 체크 시
    ? "기본 이미지 업로드를 선택하셨습니다."
    : thumbnailWatch && typeof thumbnailWatch !== "string" && thumbnailWatch.length > 0 // 새로 업로드한 파일 있을 경우
    ? (thumbnailWatch[0] as File).name
    : postDetail?.thumbnail_basic // 기존 기본 이미지 사용
    ? "기본 이미지 업로드를 선택하셨습니다."
    : postDetail?.thumbnail // 기존 일반 이미지 사용
    ? postDetail.thumbnail.split("/").pop()
    : "1000px*800px 5mb 이하 사진파일";

  const CustomInput = forwardRef<HTMLInputElement, { value?: Date | string | null; onClick?: () => void }>(
    ({ value, onClick }, ref) => (
      <SpartaTextField
        label="마감기한"
        type="small"
        inputProps={{
          placeholder: "마감기한을 선택해주세요.",
          readOnly: true,
          value: value ? getFormattedDate(value) : "",
        }}
        rightIcon={calendar}
        onRightIconClick={onClick} // 달력 열기
      />
    ),
  );

  return (
    <div className="w-full mt-10 mb-6 p-9 bg-gray-800 rounded-xl">
      <p className="font-DungGeunMo text-xl text-primary-400">프로젝트 정보 작성</p>

      <div className="flex gap-10 mt-5">
        <div className="flex flex-col gap-5 basis-1/2">
          <SpartaChipSelect
            label="구하는 포지션"
            options={roleOptions}
            control={control}
            rules={{ required: "포지션을 선택해주세요" }}
            name="want_roles"
            placeHolderText="구하는 포지션을 선택해주세요."
            multiple
          />

          <Controller
            name="deadline"
            control={control}
            rules={{ required: "날짜를 선택해주세요" }}
            render={({ field: { onChange, value, ref } }) => (
              <DatePicker
                selected={value}
                onChange={(date) => {
                  const formattedDate = date ? format(date, "yyyy-MM-dd") : "";
                  onChange(formattedDate);
                }}
                customInput={<CustomInput ref={ref} value={value} />}
                minDate={new Date()}
                dayClassName={(date) => {
                  const today = startOfDay(new Date());
                  if (isBefore(date, today)) {
                    return "text-gray-400 cursor-not-allowed";
                  }
                  return "";
                }}
                locale={ko}
                showPopperArrow={false}
                popperPlacement="bottom-end"
                portalId="datepicker-portal"
              />
            )}
          />

          <SpartaTextField
            label="연락방법"
            type="small"
            register={register("contact", {
              required: "연락방법을 입력해주세요.",
              pattern: {
                value: /^(https?:\/\/)?([\w-])+\.([a-zA-Z]{2,63})([/\w.-]*)*\/?$/,
                message: "올바른 링크를 입력해주세요.",
              },
            })}
            inputProps={{
              placeholder: "디스코드, 카카오톡 등 링크를 입력해주세요.",
            }}
            subLabel={{
              default: "",
              error: formState.errors.contact?.message as string,
              pass: "",
            }}
            error={!!formState.errors.contact}
          />

          <div className="flex flex-col gap-2">
            <SpartaTextField
              label="프로젝트 이미지"
              type="small"
              inputProps={{
                placeholder: thumbnailPlaceHolder,
                readOnly: true,
              }}
              btnContent={
                <SpartaButton
                  content="업로드"
                  disabled={selectBasicImage}
                  type="filled"
                  colorType={
                    (typeof imageWatch === "string" && imageWatch.trim().length > 0) ||
                    (imageWatch && typeof imageWatch !== "string" && imageWatch.length > 0)
                      ? "primary"
                      : "grey"
                  }
                  size="small"
                  btnType="button"
                  onClick={onClickUploadImage}
                  customStyle="w-full rounded-sm"
                />
              }
            />

            <input
              id="project-image"
              type="file"
              accept="image/*"
              {...register("thumbnail", {
                validate: (value) => {
                  if (selectBasicImage) return true;

                  if (value && value.length > 0) return true;

                  return "프로젝트 이미지를 업로드해주세요.";
                },
              })}
              className="hidden"
            />

            <div className="flex items-center gap-2">
              <SpartaCheckBox checked={isChecked} onClick={onClickSelectBasicImage} customStyle={"w-4 h-4"} />
              <p className=" text-sm text-gray-50">스파르타 기본 이미지 사용</p>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-5 basis-1/2">
          <SpartaRadioGroup
            groupsToShow={["purpose", "duration", "meeting_type"]}
            control={control}
            watch={watch}
            setValue={setValue}
            radioGroupsData={radioGroupsData}
          />
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef } from "react";
import { useFormContext } from "react-hook-form";

import SpartaTextField from "../../../../spartaDesignSystem/SpartaTextField";

import { TProjectRecruitForm } from "../../../../types";

import ReactQuill from "react-quill";
import { Quill } from "react-quill";
import { ImageDrop } from "quill-image-drop-module";
import { ImageActions } from "@xeger/quill-image-actions";
import { ImageFormats } from "@xeger/quill-image-formats";
import "react-quill/dist/quill.snow.css";
import "quill-image-uploader/dist/quill.imageUploader.min.css";

import uploadImageFileToS3 from "../../../../util/uploadImageToS3";
import base64ToFile from "../../../../util/base64ToFile";
import { EDITOR_FORMATS } from "../../../../constant/constant";

Quill.register("modules/imageDrop", ImageDrop);
Quill.register("modules/imageActions", ImageActions);
Quill.register("modules/imageFormats", ImageFormats);

export default function RecruitFormDescription() {
  const { register, watch, setValue, formState } = useFormContext<TProjectRecruitForm>();
  const quillRef = useRef<ReactQuill | null>(null);
  const editorContent = watch("content");

  useEffect(() => {
    register("content", {
      required: "프로젝트 내용을 입력해주세요.",
    });
  }, [register]);

  // 에디터 텍스트 입력, 이미지 드래그앤 드롭하는 경우
  const handleEditorChange = async (editorState: string) => {
    //이미지 드래그앤 드롭 없이 텍스트만 입력한 경우
    if (!editorState.includes("data:image")) {
      const isEmptyContent = editorState.trim() === "<p><br></p>";
      const cleanedContent = isEmptyContent ? "" : editorState;
      setValue("content", cleanedContent, { shouldValidate: true });

      return;
    }

    // 이미지 드래그앤 드롭한 경우
    const tempContainer = document.createElement("div");
    tempContainer.innerHTML = editorState;

    const images = tempContainer.querySelectorAll("img");

    for (const img of images) {
      const src = img.getAttribute("src") || "";

      if (src.startsWith("data:image")) {
        const file = base64ToFile(src, "pasted-image.png");

        try {
          const url = await uploadImageFileToS3(file);
          img.setAttribute("src", url); // base64 → S3 URL로 교체
        } catch (e) {
          console.error("이미지 업로드 실패", e);
        }
      }
    }

    const updatedHtml = tempContainer.innerHTML;

    // 에디터 내용 입력후 모두 지웠을 때 <p><br></p>로 남는 경우 빈 문자열로 세팅
    const isEmptyContent = tempContainer.innerHTML.trim() === "<p><br></p>";
    const cleanedContent = isEmptyContent ? "" : updatedHtml;

    setValue("content", cleanedContent, { shouldValidate: true });
  };

  // 에디터 내 이미지 업로드 버튼을 클릭하여 이미지 업로드하는 경우
  const onClickUploadImage = () => {
    const input = document.createElement("input");
    input.setAttribute("type", "file");
    input.setAttribute("accept", "image/*");
    input.click();

    input.onchange = async () => {
      const file = input.files ? input.files[0] : null;
      if (!file) return;

      try {
        const url = await uploadImageFileToS3(file);

        // 업로드된 이미지 URL 에디터에 삽입
        if (!quillRef.current) return;

        const editor = quillRef.current.getEditor();
        const range = editor.getSelection() || { index: editor.getLength() };

        editor.insertEmbed(range.index, "image", url);
        editor.setSelection(range.index + 1, 0);

        const updatedContent = editor.root.innerHTML;

        setValue("content", updatedContent, { shouldValidate: true });
      } catch (error) {
        console.error("이미지 업로드 실패", error);
      }
    };
  };

  // 이미지를 복사, 붙여넣기 한 경우
  const handlePasteImage = async (e: React.ClipboardEvent<HTMLDivElement>) => {
    const clipboardItems = e.clipboardData.items;

    for (let i = 0; i < clipboardItems.length; i++) {
      const item = clipboardItems[i];
      if (item.type.indexOf("image") !== -1) {
        const file = item.getAsFile();

        if (file && quillRef.current) {
          e.preventDefault(); // 브라우저가 이미지를 자동으로 base64형태로 변환하는 작업 방지

          const editor = quillRef.current.getEditor();
          const url = await uploadImageFileToS3(file);
          const range = editor.getSelection() || { index: editor.getLength() };

          editor.insertEmbed(range.index, "image", url);
          editor.setSelection(range.index + 1, 0);
        }
      }
    }
  };

  const modules = useMemo(() => {
    return {
      imageActions: {},
      imageFormats: {},
      toolbar: {
        container: [
          [{ header: [1, 2, false] }],
          ["bold", "italic", "underline", "strike"],
          [{ list: "ordered" }, { list: "bullet" }, { indent: "-1" }, { indent: "+1" }],
          ["image"],
          [{ align: [] }, { color: [] }, { background: [] }],
        ],
        handlers: {
          image: onClickUploadImage,
        },
        ImageResize: {
          modules: ["Resize"],
        },
      },
      imageDrop: true,
    };
  }, []);

  return (
    <div className="w-full mt-10 mb-6 p-9 bg-gray-800 rounded-xl">
      <p className="font-DungGeunMo text-xl text-primary-400">상세내용 작성</p>

      <div className="mt-5">
        <SpartaTextField
          label="글 제목"
          type="small"
          register={register("title", {
            required: "프로젝트 제목을 입력해주세요.",
            maxLength: { value: 100, message: "최대 100자까지 입력할 수 있습니다." },
          })}
          inputProps={{
            placeholder: "핵심 내용을 간략하게 적어보세요.",
            maxLength: 100,
          }}
          subLabel={{
            default: "",
            error: formState.errors.title?.message as string,
            pass: "",
          }}
          error={!!formState.errors.title}
        />
      </div>

      <div className="flex flex-col gap-[10px] my-5 formContent">
        <div className="flex items-end gap-2 font-semibold text-gray-100">프로젝트 소개</div>

        <div onPaste={handlePasteImage}>
          <ReactQuill
            ref={quillRef}
            theme="snow"
            value={editorContent}
            modules={modules}
            formats={EDITOR_FORMATS}
            onChange={handleEditorChange}
            placeholder="프로젝트에 대해 자세히 적어주세요.&#10;예시를 참고해 작성한다면 좋은 팀원을 구할 수 있을거에요.&#10;&#10;예시)&#10;• 프로젝트의 게임 분야 (FPS, RPG 등)&#10;• 프로젝트를 시작하게 된 배경&#10;• 프로젝트의 목표&#10;• 프로젝트에 할애할 수 있는 시간&#10;• 그동안 나의 경험과 강점 (다른 프로젝트를 해봤어요, 열정이 넘쳐요 등)&#10;• 우리 팀의 분위기와 강점 (이미 합류한 팀원이 있다면 적어주세요.)&#10;• 프로젝트 관련 주의사항"
            className="text-white"
          />
        </div>
      </div>
    </div>
  );
}

import { Modal, Box } from "@mui/material";
import { useEffect, useState } from "react";
import { Swiper, SwiperRef, SwiperSlide } from "swiper/react";
import useModalToggle from "../../../hook/useModalToggle";
import { Pagination } from "swiper/modules";

import "swiper/css";
import "./GamePlaySwiper.css";

type Props = {
  screenShotList?: {
    id: number;
    src: string;
  }[];
  swiperRef: React.RefObject<SwiperRef>;
};
const ScreenShotModal = ({ screenShotList, swiperRef }: Props) => {
  const { modalToggle, onClickModalToggleHandler } = useModalToggle();
  const [imageIndex, setImageIndex] = useState(0);

  useEffect(() => {
    if (swiperRef.current) {
      const swiperInstance = swiperRef.current.swiper;

      const onClickSlide = (e: MouseEvent) => {
        const slideElement = (e.target as HTMLElement).closest(".swiper-slide");

        if (slideElement) {
          const slideIndex = slideElement.getAttribute("data-swiper-slide-index");

          if (slideIndex !== null && screenShotList) {
            setImageIndex(Number(slideIndex));
            onClickModalToggleHandler();
          }
        }
      };

      swiperInstance.slides?.forEach((slide: HTMLElement) => {
        slide.addEventListener("click", onClickSlide);
      });

      return () => {
        swiperInstance.slides?.forEach((slide: HTMLElement) => {
          slide.removeEventListener("click", onClickSlide);
        });
      };
    }
  }, [screenShotList]);

  return (
    <Modal open={modalToggle} onClose={onClickModalToggleHandler} disableScrollLock={true}>
      <Box className="fixed top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 rounded-3xl outline-none border border-solid border-primary-500 bg-gray-800 p-8 max-w-[750px] max-h-full overflow-auto">
        <Swiper
          pagination={{
            clickable: true,
          }}
          loop={screenShotList && screenShotList?.length > 3 ? true : false}
          centeredSlides={true}
          slidesPerView={screenShotList?.length === 1 ? 1 : 2}
          modules={[Pagination]}
          initialSlide={imageIndex}
          className="stillCutSwiper"
        >
          {screenShotList?.map((image, index) => (
            <SwiperSlide key={index}>
              <img
                src={
                  import.meta.env.VITE_DEPLOYMENT_MODE === "dev"
                    ? import.meta.env.VITE_PROXY_HOST + image.src
                    : image.src
                }
                alt={`carousel-img-${index}`}
              />
            </SwiperSlide>
          ))}
        </Swiper>
      </Box>
    </Modal>
  );
};

export default ScreenShotModal;

