  const { currentPage, onChangePage } = usePageHandler();
  const { modalToggle, onClickModalToggleHandler } = useModalToggle();

  const queryClient = useQueryClient();

  const { data: allReviewData } = useQuery<TReviewResponse>({
    queryKey: ["reviews", currentPage, selectedOrder],
    queryFn: () =>
      userData
        ? getGameReviews(gamePk, currentPage, COUNT_PER_PAGE, selectedOrder, userData.data)
        : getGameReviews(gamePk, currentPage, COUNT_PER_PAGE, selectedOrder),
  });

  const { data: myReviewData } = useQuery<TReviewResponse>({
    queryKey: ["reviews", "my_review", gamePk],
    queryFn: () => getGameMyReview(gamePk, currentPage, COUNT_PER_PAGE),
    enabled: !!userData,
  });

  const allReviews = useMemo(() => {
    return allReviewData?.data.all_reviews ?? [];
  }, [allReviewData]);

  const myReview = myReviewData?.data.my_review ?? null;

  useEffect(() => {
    if (allReviews) {
      const reviewsWithoutMyReview = allReviews.filter((review) => review.id !== myReview?.id);
      setReviewList(reviewsWithoutMyReview);
    }
  }, [allReviews, myReview?.id]);

  useEffect(() => {
    queryClient.invalidateQueries({ queryKey: ["reviews"] });
  }, [myReviewData]);

  return (
    <>
      <section className="flex flex-col gap-3 mb-12">
        <div className="flex justify-between">
          <p className="text-3xl font-DungGeunMo text-white">Review</p>
          <div className="flex gap-3 text-xl font-semibold text-white">
            <p
              onClick={() => setSelectedOrder("new")}
              className={`cursor-pointer ${selectedOrder === "new" ? "text-primary-500" : "text-white"}`}
            >
              최근 게시순
            </p>
            <p
              onClick={() => setSelectedOrder("likes")}
              className={`cursor-pointer ${selectedOrder === "likes" ? "text-primary-500" : "text-white"}`}
            >
              공감 많은순
            </p>
            <p
              onClick={() => setSelectedOrder("dislikes")}
              className={`cursor-pointer ${selectedOrder === "dislikes" ? "text-primary-500" : "text-white"}`}
            >
              비공감 많은 순
            </p>
          </div>
        </div>
        <div className="grid grid-cols-3 gap-5">
          {currentPage === 1 &&
            (userData ? (
              !myReview ? (
                <div
                  onClick={() => {
                    onClickModalToggleHandler();
                    setIsRegister(true);
                  }}
                  className=" flex items-center justify-center gap-6 h-[245px] border border-solid border-primary-500 bg-gray-800 rounded-xl cursor-pointer"
                >
                  <img src={reviewRegister} />
                  <p className="text-white font-DungGeunMo text-2xl">내 리뷰 등록하기</p>
                </div>
              ) : (
                <ReviewCard
                  onClickModalToggleHandler={onClickModalToggleHandler}
                  review={myReview}
                  isMyReview={!!myReview}
                  setIsRegister={setIsRegister}
                />
              )
            ) : (
              <div className="flex items-center justify-center gap-6 px-11 h-[245px] border border-solid border-alert-default hover:border-alert-hover bg-gray-800 rounded-xl">
                <img src={reviewRegister} />
                <p className="text-white font-DungGeunMo text-2xl text-center leading-none">
                  비회원은 리뷰등록이 불가능합니다.
                </p>
              </div>
            ))}

          {reviewList?.map((review) => (
            <ReviewCard review={review} onClickModalToggleHandler={onClickModalToggleHandler} />
          ))}
        </div>
        <SpartaPagination
          dataTotalCount={allReviewData?.pagination.count}
          countPerPage={COUNT_PER_PAGE}
          onChangePage={onChangePage}
        />
      </section>

      <ReviewRegisterModal
        gamePk={gamePk}
        modalToggle={modalToggle}
        onClickModalToggleHandler={onClickModalToggleHandler}
        myReview={myReview}
        isRegister={isRegister}
      />
    </>
  );
};

export default ReviewContents;

import { useState, useEffect } from "react";

import { Modal, Box } from "@mui/material";
import Rating from "@mui/material/Rating";

import useReview from "../../../hook/gameDetailHook/useReview";

import DifficultyChip from "../../common/chipComponents/DifficultyChip";

import closeBtn from "../../../assets/common/closeBtn.svg";
import star from "../../../assets/star.svg";
import fillStar from "../../../assets/fillStar.svg";
import grayStar from "../../../assets/grayStar.svg";
import SpartaReactionModal from "../../../spartaDesignSystem/SpartaReactionModal";
import { TReviewData } from "../../../types";
import SpartaButton from "../../../spartaDesignSystem/SpartaButton";

type Props = {
  gamePk: number;
  modalToggle: boolean;
  onClickModalToggleHandler: () => void;
  myReview: TReviewData | null;
  isRegister: boolean;
};

const ReviewRegisterModal = ({ gamePk, modalToggle, onClickModalToggleHandler, myReview, isRegister }: Props) => {
  const { review, form, eventHandler } = useReview();

  const [ratingValue, setRatingValue] = useState<number | null>(null);
  const [selectedDifficulty, setSelectedDifficulty] = useState("");
  const [isHovered, setIsHovered] = useState(false);

  const gameDifficulty: ("EASY" | "NORMAL" | "HARD")[] = ["EASY", "NORMAL", "HARD"];

  const editorContent = form.watch("content");

  const onHoverEnter = () => {
    setIsHovered(true);
  };

  const onHoverLeave = () => {
    setIsHovered(false);
  };

  const resetForm = () => {
    form.setValue("content", "");
    setRatingValue(null);
    setSelectedDifficulty("");
  };

  useEffect(() => {
    if (myReview) {
      const convertedDifficulty = convertDifficulty(myReview?.difficulty, true) as string;

      setRatingValue(myReview?.star);
      setSelectedDifficulty(convertedDifficulty);
      form.setValue("content", myReview?.content), { shouldValidate: true };

      form.trigger();
    } else {
      resetForm();
    }
  }, [myReview]);

  const onClickReviewRegisterHandler = () => {
    const difficulty = convertDifficulty(selectedDifficulty, false) as number;
    eventHandler.onSubmitHandler(gamePk, difficulty, ratingValue, editorContent);

    onClickModalToggleHandler();
  };

  const onClickReviewEditHandler = () => {
    const difficulty = convertDifficulty(selectedDifficulty, false) as number;

    eventHandler.onSubmitReviewEditHandler(
      myReview?.id,
      myReview?.game_id,
      difficulty,
      ratingValue,
      myReview?.star,
      editorContent,
    );

    onClickModalToggleHandler();
  };

  const onClickDifficulty = (level: "EASY" | "NORMAL" | "HARD") => {
    setSelectedDifficulty(level);
  };

  const convertDifficulty = (difficulty: string | number, toString: boolean) => {
    if (toString) {
      switch (difficulty) {
        case 0:
          return "EASY";
        case 1:
          return "NORMAL";
        case 2:
          return "HARD";
      }
    } else {
      switch (difficulty) {
        case "EASY":
          return 0;
        case "NORMAL":
          return 1;
        case "HARD":
          return 2;
      }
    }
  };

  return (
    <>
      <Modal open={modalToggle} disableScrollLock={true}>
        <Box className="fixed left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 border border-solid border-primary-500 rounded-xl bg-gray-800 outline-none">
          <div className="flex flex-col gap-4 p-8 w-[1000px]">
            <div className="flex justify-between items-center">
              <p className="text-3xl font-DungGeunMo text-primary-500">{isRegister ? "리뷰등록" : "리뷰수정"}</p>
              <img
                onClick={() => onClickModalToggleHandler()}
                className="w-7 h-7 cursor-pointer"
                src={closeBtn}
                alt="닫기"
              />
            </div>

            <div className="flex items-center gap-8">
              <p className="text-2xl font-DungGeunMo text-white whitespace-nowrap">게임의 난이도는?</p>
              <div className="flex gap-3">
                {gameDifficulty.map((level) => (
                  <DifficultyChip
                    key={level}
                    chipSize="big"
                    difficultyLevel={level}
                    selectedDifficulty={selectedDifficulty}
                    isSelected={selectedDifficulty === level}
                    onClick={() => onClickDifficulty(level)}
                  />
                ))}
              </div>
            </div>

            <div className="flex gap-14">
              <p className="text-2xl font-DungGeunMo text-white">게임의 점수는?</p>

              <Rating
                name="gameRating"
                value={ratingValue}
                onChange={(event: React.SyntheticEvent, newValue: number | null): void => {
                  setRatingValue(newValue);
                }}
                sx={{
                  width: "120px",
                }}
                icon={<img src={fillStar} width={30} height={30} />}
                emptyIcon={<img src={ratingValue === null && !isHovered ? grayStar : star} width={30} height={30} />}
                onMouseEnter={onHoverEnter}
                onMouseLeave={onHoverLeave}
              />
            </div>

            <div className="flex items-start gap-10">
              <div>
                <p className="text-2xl font-DungGeunMo text-white whitespace-nowrap">리뷰내용 입력</p>
                <span className="text-sm font-DungGeunMo text-white">(최대 300자)</span>
              </div>

              <div className="border border-solid border-gray-100 p-2 w-full h-52 rounded-lg">
                <textarea
                  placeholder="소중한 리뷰 감사합니다 :)"
                  {...form.register("content", { required: true, maxLength: 300 })}
                  {...form.register("content", { required: "필수" })}
                  className="p-2 w-full h-full text-lg leading-tight text-white bg-transparent outline-none resize-none"
                />
              </div>
            </div>

            <SpartaButton
              content={
                editorContent?.length > 300
                  ? "리뷰는 300자 이내로 입력바랍니다."
                  : !form.formState.isValid || ratingValue === null || selectedDifficulty === ""
                  ? "세가지 모두 입력해주세요!"
                  : isRegister
                  ? "리뷰를 등록합니다"
                  : "리뷰를 수정합니다."
              }
              onClick={myReview ? onClickReviewEditHandler : onClickReviewRegisterHandler}
              type={"filled"}
              colorType={
                !form.formState.isValid || ratingValue === null || selectedDifficulty === "" ? "grey" : "primary"
              }
              disabled={editorContent?.length > 300}
            />
          </div>
        </Box>
      </Modal>

      {review.noActionModalData && (
        <SpartaReactionModal
          isOpen={review.modalToggles[review.NO_ACTION_MODAL_ID]}
          onClose={review.onClickModalToggleHandlers[review.NO_ACTION_MODAL_ID]}
          modalId={review.NO_ACTION_MODAL_ID}
          title={review.noActionModalData.title || ""}
          content={review.noActionModalData.content || ""}
          btn1={{
            text: review.noActionModalData?.btn1?.text || "",
            onClick: review.noActionModalData?.btn1?.onClick || (() => {}),
          }}
          type={review.noActionModalData.type}
        />
      )}
    </>
  );
};

export default ReviewRegisterModal;

import { useQuery } from "@tanstack/react-query";
