import { useEffect, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useLocation, useNavigate, useParams, useSearchParams } from "react-router-dom";

import { getUserData } from "../api/user";

import Logs from "../components/mypageComponents/Logs";
import Setting from "../components/mypageComponents/Settting";
import ProfileHeader from "../components/mypageComponents/ProfileHeader";
import MyGame from "../components/mypageComponents/MyGame";
import ProfileDetail from "../components/communityComponents/TeamBuilding/Profile/ProfileDetail";

import { userStore } from "../share/store/userStore";
import { TUserDataResponse } from "../types";

const MyPage = () => {
  const [navigation, setNavigation] = useState<"log" | "teambuilding" | "develop" | "setting">("log");

  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [result, setResult] = useState<"review" | "saved" | null>(location.state?.gameResult || null);
  useEffect(() => {
    if (location.state?.gameResult) navigate(location.pathname + location.search, { replace: true, state: null });
  }, [location, navigate]);
  const [searchParams] = useSearchParams();

  const tabParam = searchParams.get("tab");

  const navigationButtonConfig = {
    clicked: "bg-gray-700 text-primary-500",
    unClicked: "bg-gray-800 text-gray-400",
  };

  const { userData } = userStore();
  const isUserDataLoaded = !!userData?.data?.user_id;
  const isMyPage = isUserDataLoaded ? id === userData.data.user_id.toString() : null;

  useEffect(() => {
    if (!isUserDataLoaded) return;

    if (!isMyPage) {
      window.alert("잘못된 접근입니다.");
      navigate("/", { replace: true });
    }

    if (!tabParam) {
      navigate(`?tab=log`, { replace: true });
    }
  }, [id, userData, navigate]);

  const { data, isError } = useQuery<TUserDataResponse>({
    queryKey: ["userProfile", id],
    queryFn: () => getUserData(Number(id)),
    enabled: !!id && !isMyPage,
    retry: 1,
  });

  const user = isMyPage ? userData?.data : data?.data;

  useEffect(() => {
    if (isError) {
      window.alert("존재하지 않는 사용자입니다.");
      window.history.back();
    }
    if (isMyPage) {
      // tab 쿼리 파라미터가 있을 경우 해당 탭으로 초기화
      if (tabParam === "log" || tabParam === "teambuilding" || tabParam === "develop" || tabParam === "setting") {
        setNavigation(tabParam);
      } else {
        setNavigation("log");
      }
    } else {
      setNavigation("develop");
    }
  }, [id, userData, isError]);

  const handleTabChange = (tab: typeof navigation) => {
    setNavigation(tab);
    navigate(`?tab=${tab}`, { replace: true });
  };

  return (
    user && (
      <div className="w-full">
        <div className="relative flex flex-col">
          <div className="flex gap-9 py-11 w-[1180px] mx-auto">
            <div className="bg-gray-800 w-[15%] p-2 rounded-xl h-fit">
              {isMyPage && (
                <button
                  className={`w-full h-12 rounded-xl text-heading-20 
            ${navigation === "log" ? navigationButtonConfig.clicked : navigationButtonConfig.unClicked}
              `}
                  onClick={() => handleTabChange("log")}
                >
                  활동목록
                </button>
              )}

              <button
                className={`w-full h-12 rounded-xl text-heading-20  ${
                  navigation === "teambuilding" ? navigationButtonConfig.clicked : navigationButtonConfig.unClicked
                }`}
                onClick={() => handleTabChange("teambuilding")}
              >
                팀빌딩 프로필
              </button>

              <button
                className={`w-full h-12 rounded-xl text-heading-20  ${
                  navigation === "develop" ? navigationButtonConfig.clicked : navigationButtonConfig.unClicked
                }`}
                onClick={() => handleTabChange("develop")}
              >
                개발목록
              </button>
              {isMyPage && (
                <button
                  className={`w-full h-12 rounded-xl  text-heading-20  ${
                    navigation === "setting" ? navigationButtonConfig.clicked : navigationButtonConfig.unClicked
                  }`}
                  onClick={() => handleTabChange("setting")}
                >
                  정보설정
                </button>
              )}
            </div>
            <div className="w-[85%]">
              {result && (
                <div role="status" className="p-4 mb-4 text-white bg-gray-700">
                  <strong>{result === "review" ? "검수 요청 완료" : "변경사항이 저장되었습니다."}</strong>
                  {result === "review" && <p>검수 완료 시 알림으로 안내합니다.</p>}
                  <button onClick={() => setResult(null)}>닫기</button>
                </div>
              )}
              <ProfileHeader user={user} isMyPage={isMyPage} setNavigation={setNavigation} />
              {navigation === "log" ? (
                <Logs user={user} />
              ) : navigation === "teambuilding" && user ? (
                <ProfileDetail user={user} isMyPage={isMyPage} />
              ) : navigation === "develop" ? (
                <MyGame submissionComplete={result === "review"} user={user} isMyPage={isMyPage} />
              ) : (
                <Setting />
              )}
            </div>
          </div>
        </div>
      </div>
    )
  );
};

export default MyPage;

import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import { discordLogin, googleLogin, kakaoLogin, naverLogin } from "../api/login";
import loading from "../assets/common/loading.gif";
import { userStore } from "../share/store/userStore";
import axios from "axios";
import useModalToggles from "../hook/useModalToggles";
import SpartaReactionModal, { TSpartaReactionModalProps } from "../spartaDesignSystem/SpartaReactionModal";

const Redirect = () => {
  const NO_ACTION_MODAL_ID = "noActionModal";
  const { modalToggles, onClickModalToggleHandlers } = useModalToggles([NO_ACTION_MODAL_ID]);

  const { service } = useParams();
  const [searchParams] = useSearchParams();
  const code = searchParams.get("code");

  const navigate = useNavigate();
  const { setUser } = userStore();

  const [noActionModalData, setNoActionModalData] = useState<Partial<TSpartaReactionModalProps>>({});

  const switchFetchApiByService = (service: string) => {
    switch (service) {
      case "kakao":
        return kakaoLogin(code!);
      case "naver":
        return naverLogin(code!);
      case "discord":
        return discordLogin(code!);
      case "google":
        return googleLogin(code!);
      default:
        return;
    }
  };

  const { data, error, isError } = useQuery<any>({
    queryKey: ["loginData", code],
    queryFn: () => {
      return switchFetchApiByService(service!);
    },
    enabled: !!code && !!service,
    retry: false,
  });

  const email = data?.data?.data.email;
  const logint_tpye = data?.data?.data.login_type;

  useEffect(() => {
    if (isError && axios.isAxiosError(error)) {
      if (error.response?.status === 400) {
        setNoActionModalData({
          title: "로그인 실패",
          content: error?.response.data?.message,
          btn1: {
            text: "확인했습니다.",
            onClick: () => {
              onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();
              navigate("/");
            },
          },
          type: "error",
        });
        onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();

        return;
      } else if (error.response?.status === 401) {
        setNoActionModalData({
          title: "로그인 실패",
          content: error?.response.data?.message,
          btn1: {
            text: "확인했습니다.",
            onClick: () => {
              onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();
              navigate("/");
            },
          },
          type: "error",
        });
        onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();

        return;
      } else if (error.response?.status === 500) {
        setNoActionModalData({
          title: "로그인 실패",
          content: error?.response.data?.message,
          btn1: {
            text: "확인했습니다.",
            onClick: () => {
              onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();
              navigate("/");
            },
          },
          type: "error",
        });
        onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();

        return;
      }
    }

    if (!data) return;

    const redirectPath = sessionStorage.getItem("redirectPath") || "/";

    if (data?.data?.message?.includes("회원가입")) {
      //회원가입 페이지로 이동
      navigate(`/signup?email=${email}&login_type=${logint_tpye}`);
    } else {
      sessionStorage.setItem("accessToken", data?.data.data.access);
      sessionStorage.setItem("refreshToken", data?.data.data.refresh);
      //메인 페이지로 이동
      setUser(data.data?.data.access);
      navigate(redirectPath);
      sessionStorage.removeItem("redirectPath");
    }
  }, [data, isError]);

  return (
    <>
      <div className="flex flex-col justify-center items-center h-screen gap-3 bg-white">
        {/* <CircularProgress size="3rem" /> */}
        <img src={loading} className="w-[200px] h-30" />
        <div className="font-DungGeunMo  text-heading-28 mt-5">소셜로그인을 진행중입니다... </div>
        <div className="font-DungGeunMo text-heading-28">잠시만 기다려주세요! </div>
      </div>

      {noActionModalData && (
        <SpartaReactionModal
          isOpen={modalToggles[NO_ACTION_MODAL_ID]}
          onClose={onClickModalToggleHandlers[NO_ACTION_MODAL_ID]}
          modalId={NO_ACTION_MODAL_ID}
          title={noActionModalData.title || ""}
          content={noActionModalData.content || ""}
          btn1={{
            text: noActionModalData?.btn1?.text || "",
            onClick: noActionModalData?.btn1?.onClick || (() => {}),
          }}
          type={noActionModalData.type}
        />
      )}
    </>
  );
};

export default Redirect;

import { passwordValidation, PASSWORD_HELP } from "../util/accountValidation";
import React, { useEffect, useState } from "react";
import pixelMeteor from "../assets/homeImage/pixelMeteor.svg";
import heroImage from "../assets/homeImage/heroImage.svg";
import { useForm } from "react-hook-form";
import SpartaButton from "../spartaDesignSystem/SpartaButton";
import useModalToggles from "../hook/useModalToggles";
import SpartaReactionModal, { TSpartaReactionModalProps } from "../spartaDesignSystem/SpartaReactionModal";
import SpartaTextField from "../spartaDesignSystem/SpartaTextField";
import { postEmailVerify, postSendEmailCode } from "../api/login";
import { convertToMMSS } from "../util/convertToMMSS";
import { resetPassword, resetPasswordVerify } from "../api/user";

type Props = {};

const ResetPassword = (props: Props) => {
  const {
    register,
    formState: { errors, isValid },
    handleSubmit,
    trigger,
    watch,
  } = useForm({
    mode: "onChange",
    defaultValues: {
      email: "",
      email_code: null,
      password: "",
      password_check: "",
    },
  });

  const email = watch("email");
  const emailCode = watch("email_code") ?? 0;
  const password = watch("password");
  const password_check = watch("password_check");

  const NO_ACTION_MODAL_ID = "noReactionModal";

  const { modalToggles, modalRefs, onClickModalToggleHandlers } = useModalToggles([NO_ACTION_MODAL_ID]);

