      title: "이메일 인증 완료",
      content: "이메일 인증이 완료되었습니다. 비밀번호 변경 진행이 가능합니다.",
      btn1: {
        text: "확인했습니다",
        onClick: () => {
          onClickModalToggleHandlers[NO_ACTION_MODAL_ID]();
        },
      },
      type: "primary",
    },
    changePasswordComplete: {
